from json import dumps


class Tree:
    def __init__(self, label, children=None):
        self.label = label
        self.children = children if children is not None else []

    def __dict__(self):
        return {self.label: [c.__dict__() for c in sorted(self.children)]}

    def __str__(self, indent=None):
        return dumps(self.__dict__(), indent=indent)

    def __lt__(self, other):
        return self.label < other.label

    def __eq__(self, other):
        return self.__dict__() == other.__dict__()

    def from_pov(self, from_node):
        return self._rotate(from_node, None)

    def _rotate(self, from_node, parent):
        if self.label == from_node:
            node = Tree(self.label, list(self.children))
            if parent is not None:
                node.children.append(parent)
            return node

        for child in self.children:
            if from_node in child._labels():
                new_self = Tree(self.label, [c for c in self.children if c is not child])
                if parent is not None:
                    new_self.children.append(parent)
                return child._rotate(from_node, new_self)

        raise ValueError("Tree could not be reoriented")

    def _labels(self):
        return [self.label] + [
            label for child in self.children for label in child._labels()
        ]

    def path_to(self, from_node, to_node):
        reoriented = self.from_pov(from_node)
        path = reoriented._find_path(to_node)
        if path is None:
            raise ValueError("No path found")
        return path

    def _find_path(self, to_node):
        if self.label == to_node:
            return [self.label]
        for child in self.children:
            subpath = child._find_path(to_node)
            if subpath is not None:
                return [self.label] + subpath
        return None

